 private String hash(Map<String,Object>o){Map<String,Object>root=new LinkedHashMap<>();for(String k:List.of("customerId","paymentType","currency","taxMode"))root.put(k,o.get(k));List<Object>list=new ArrayList<>();for(var l:readLines(o)){Map<String,Object>m=new LinkedHashMap<>();for(String k:List.of("id","productId","unit","factor","qty","baseQty","price","stdPrice","priceSource","priceRefId","priceVersionNo","manualPriceFlag","discountAmount","taxRate"))m.put(k,l.get(k));m.put("allocs",ls(l,"allocs").stream().map(a->Map.of("id",a.get("id"),"warehouseId",a.get("warehouseId"),"allocQty",a.get("allocQty"))).toList());list.add(m);}root.put("lines",list);return Digests.sha256(json.write(IdempotencyExecutor.canonical(root)));}
