 private void refresh(Access a,long oid){j.update("UPDATE sal_order o SET total_qty=(SELECT COALESCE(sum(base_qty-cancelled_qty),0) FROM sal_order_line WHERE country_id=o.country_id AND order_id=o.id),total_amount=(SELECT COALESCE(sum(round(line_amount*(base_qty-cancelled_qty)/base_qty,4)),0) FROM sal_order_line WHERE country_id=o.country_id AND order_id=o.id),fulfillment_status=CASE WHEN EXISTS(SELECT 1 FROM sal_order_line l WHERE l.country_id=o.country_id AND l.order_id=o.id) AND NOT EXISTS(SELECT 1 FROM sal_order_line l WHERE l.country_id=o.country_id AND l.order_id=o.id AND l.base_qty<>l.cancelled_qty) THEN 'CANCELLED' WHEN NOT EXISTS(SELECT 1 FROM sal_order_line l WHERE l.country_id=o.country_id AND l.order_id=o.id AND l.signed_qty<l.base_qty-l.cancelled_qty) THEN 'SIGNED' WHEN NOT EXISTS(SELECT 1 FROM sal_order_line l WHERE l.country_id=o.country_id AND l.order_id=o.id AND l.outbound_qty<l.base_qty-l.cancelled_qty) THEN 'OUTBOUNDED' WHEN EXISTS(SELECT 1 FROM sal_order_line l WHERE l.country_id=o.country_id AND l.order_id=o.id AND l.outbound_qty>0) THEN 'PARTIAL_OUTBOUND' WHEN o.approval_status='APPROVED' THEN 'PENDING_OUTBOUND' ELSE 'PENDING_PREPARE' END,version=version+1 WHERE country_id=? AND id=?",a.requireCountry(),oid);var o=order(a,oid,false);j.update("UPDATE sal_order SET payment_status=? WHERE country_id=? AND id=?",o.get("paymentStatus"),a.requireCountry(),oid);}
